          if (seen[link]) continue; seen[link] = true;
          var title = clean((block.match(/class=["'][^"']*(?:title|name|short-title|item-title)[^"']*["'][^>]*>([\s\S]*?)<\//i) || [])[1] || block.replace(/<img[\s\S]*?>/ig, ''));
          if (!title) title = clean(block);
          var year = firstYear(block);
